// Multiple patterns to catch various name introduction formats
const patterns = [
  /\bmy\s+name\s+is\s+([A-Za-z\u00C0-\u00FF][A-Za-z\u00C0-\u00FF'\-\s]{1,80})/i,
  /\bi'?m\s+([A-Za-z\u00C0-\u00FF][A-Za-z\u00C0-\u00FF'\-\s]{1,80})/i,
